    14	
    15	#include <QImage>
    16	#include <QScopedPointer>
    17	
    18	#include <kzip.h>
    19	
    20	static constexpr char s_magic[] = "image/openraster";
    21	static constexpr int s_magic_size = sizeof(s_magic) - 1; // -1 to remove the last \0
    22	
    23	OraHandler::OraHandler()
    24	{
    25	}
    26	
    27	bool OraHandler::canRead() const
    28	{
    29	    if (canRead(device())) {
    30	        setFormat("ora");
    31	        return true;
    32	    }
    33	    return false;
    34	}
    35	
    36	bool OraHandler::read(QImage *image)
    37	{
    38	    KZip zip(device());
    39	    if (!zip.open(QIODevice::ReadOnly)) return false;
    40	
    41	    const KArchiveEntry *entry = zip.directory()->entry(QLatin1String("mergedimage.png"));
    42	    if (!entry || !entry->isFile()) return false;
    43	
    44	    const KZipFileEntry* fileZipEntry = static_cast<const KZipFileEntry*>(entry);
    45	
    46	    image->loadFromData(fileZipEntry->data(), "PNG");
    47	
    48	    return true;
    49	}
    50	
    51	bool OraHandler::canRead(QIODevice *device)
    52	{
    53	    if (!device) {
    54	        qWarning("OraHandler::canRead() called with no device");
    55	        return false;
    56	    }
    57	
    58	    char buff[54];
    59	    if (device->peek(buff, sizeof(buff)) == sizeof(buff))
    60	        return memcmp(buff + 0x26, s_magic, s_magic_size) == 0;
    61	
    62	    return false;
    63	}
    64	
    65	QImageIOPlugin::Capabilities OraPlugin::capabilities(QIODevice *device, const QByteArray &format) const
    66	{
    67	    if (format == "ora" || format == "ORA") {
    68	        return Capabilities(CanRead);
    69	    }
    70	    if (!format.isEmpty()) {
    71	        return {};
    72	    }
    73	    if (!device->isOpen()) {
    74	        return {};
    75	    }
    76	
    77	    Capabilities cap;
    78	    if (device->isReadable() && OraHandler::canRead(device)) {
    79	        cap |= CanRead;
    80	    }
    81	    return cap;
    82	}
    83	
    84	QImageIOHandler *OraPlugin::create(QIODevice *device, const QByteArray &format) const
    85	{
    86	    QImageIOHandler *handler = new OraHandler;
    87	    handler->setDevice(device);
    88	    handler->setFormat(format);
    89	    return handler;
    90	}
